2	import { describe, test, expect, vi, beforeEach } from 'vitest';
3	import { render, screen, waitFor } from '@testing-library/react';
4	import userEvent from '@testing-library/user-event';
5	import { ChakraProvider } from '@chakra-ui/react';
6	import theme from 'app/theme';
7	import { ZimmCartDrawer } from './index';
8	
9	// ZimmIcon has a known Vitest breakage — SVG imports resolve to raw path strings in this
10	// environment, causing a top-level side effect on the SFCC icons barrel to throw. ZimmDrawer's
11	// close button renders through ZimmButton -> ZimmIcon, so any test rendering the real ZimmDrawer
12	// (this whole file does, deliberately — see the comment below) needs this same mock. See
13	// testing.md's "Known gap: ZimmIcon throws under Vitest" and zimmButton/index.test.tsx for the
14	// identical precedent.
15	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
16	
17	// This suite renders the REAL ZimmDrawer/Chakra Drawer/framer-motion throughout (nothing about
18	// the close mechanics is mocked), so Escape, backdrop-click, close-button, focus-restore and
19	// scroll-lock-restore all exercise ZimmDrawer's actual logic rather than a stand-in.
20	//
21	// A framer-motion AnimatePresence stub was tried here and reverted: Chakra's own
22	// ModalFocusScope (@chakra-ui/modal/dist/index.js) calls framer-motion's `usePresence()`
23	// itself, alongside — separately from — the `onExitComplete` prop ZimmDrawer's
24	// `onCloseComplete` depends on. A stub that only re-implements the `onExitComplete` callback
25	// (and doesn't also provide the real `usePresence` context, a materially bigger surface to
26	// reimplement faithfully) desynchronised FocusLock's own restore-focus timing from the real
27	// app's. Real framer-motion's ~300ms exit transition does complete correctly under this
28	// project's jsdom + Vitest setup; `waitFor`'s polling absorbs the wall-clock cost.
29	
30	/** Mirrors real usage: the drawer starts CLOSED and only opens in response to a real click on
31	 *  its own trigger — never pre-opened on mount. This matters specifically for the focus-restore
32	 *  assertion below: Chakra's FocusLock (inside ZimmDrawer) captures "whichever element was
33	 *  active" at the moment IT activates as its own default restore-focus target, and
34	 *  userEvent.click() genuinely focuses the element it clicks (matching real Chrome/Firefox
35	 *  click behaviour) — so opening via a real click leaves the trigger focused *before* the
36	 *  drawer (and FocusLock) mounts, the same as real usage, rather than the drawer simply
37	 *  starting pre-opened with nothing having been focused at all. onCloseSpy observes that
38	 *  ZimmCartDrawer's onClose contract fires; the harness still has to actually flip isOpen
39	 *  itself (ZimmCartDrawer does not manage its own open state) so the real close path — and
40	 *  therefore the scroll-lock cleanup and onCloseComplete — actually run. */
41	function CartDrawerHarness({ onCloseSpy }: { onCloseSpy: () => void }) {
42	  const [isOpen, setIsOpen] = useState(false);
43	  const triggerRef = useRef<HTMLButtonElement>(null);
44	  return (
45	    <ChakraProvider theme={theme}>
46	      <button ref={triggerRef} onClick={() => setIsOpen(true)}>
47	        Open bag
48	      </button>
49	      <ZimmCartDrawer
50	        isOpen={isOpen}
51	        onClose={() => {
52	          onCloseSpy();
53	          setIsOpen(false);
54	        }}
55	        itemCount={3}
56	        finalFocusRef={triggerRef}
57	      >
58	        <p>Line items</p>
59	      </ZimmCartDrawer>
60	    </ChakraProvider>
61	  );
62	}
63	
64	/** Renders the harness and opens it via a real click on its own trigger — see
65	 *  CartDrawerHarness's own doc comment for why this matters. Returns the trigger element too,
66	 *  since the focus-restore test needs to assert on it by reference after the dialog unmounts. */
67	async function renderOpenCartDrawer(onCloseSpy: () => void) {
68	  render(<CartDrawerHarness onCloseSpy={onCloseSpy} />);
69	  const trigger = screen.getByRole('button', { name: 'Open bag' });
70	  await userEvent.click(trigger);
71	  await screen.findByRole('dialog');
72	  return trigger;
73	}
74	
75	describe('ZimmCartDrawer', () => {
76	  beforeEach(() => {
77	    vi.clearAllMocks();
78	  });
79	
80	  describe('header title', () => {
81	    const renderWithItemCount = (itemCount: number) =>
82	      render(
83	        <ChakraProvider theme={theme}>
84	          <ZimmCartDrawer isOpen={true} onClose={vi.fn()} itemCount={itemCount}>
85	            <p>Line items</p>
86	          </ZimmCartDrawer>
87	        </ChakraProvider>,
88	      );
89	
90	    test('renders "BAG • {itemCount}" while there are items', async () => {
91	      renderWithItemCount(3);
92	      expect(await screen.findByRole('dialog', { name: 'BAG • 3' })).toBeInTheDocument();
93	    });
94	
95	    test('renders "BAG • {itemCount}" for a single item too (no singular/plural branching)', async () => {
96	      renderWithItemCount(1);
97	      expect(await screen.findByRole('dialog', { name: 'BAG • 1' })).toBeInTheDocument();
98	    });
99	
100	    test('renders "YOUR BAG IS EMPTY" when itemCount is 0', async () => {
101	      renderWithItemCount(0);
102	      expect(await screen.findByRole('dialog', { name: 'YOUR BAG IS EMPTY' })).toBeInTheDocument();
103	    });
104	  });
105	
106	  test('pressing Escape calls onClose', async () => {
107	    const onCloseSpy = vi.fn();
108	    await renderOpenCartDrawer(onCloseSpy);
109	
110	    await userEvent.keyboard('{Escape}');
111	
112	    expect(onCloseSpy).toHaveBeenCalledTimes(1);
113	  });
114	
115	  test('clicking the backdrop calls onClose', async () => {
116	    const onCloseSpy = vi.fn();
117	    await renderOpenCartDrawer(onCloseSpy);
118	    const dialog = screen.getByRole('dialog');
119	
120	    // ZimmDrawer's overlay-click-to-close handler (Chakra's getDialogContainerProps) lives on
121	    // ZimmDrawerContent's own outer container div, the dialog's direct DOM parent — not on
122	    // <DrawerOverlay> itself, which is purely visual (confirmed in @chakra-ui/modal/dist/
123	    // index.js: ModalOverlay carries no onClick at all). zimmDrawer/index.tsx's
124	    // ZimmDrawerContent renders `<chakra.div {...containerProps}><MotionChakraDiv
125	    // role="dialog" .../></chakra.div>` with no element in between, so the dialog's parent IS
126	    // that container. Clicking it exercises the same code path a real backdrop click does.
127	    const backdrop = dialog.parentElement as HTMLElement;
128	    await userEvent.click(backdrop);
129	
130	    expect(onCloseSpy).toHaveBeenCalledTimes(1);
131	  });
132	
133	  test('clicking the close button calls onClose', async () => {
134	    const onCloseSpy = vi.fn();
135	    await renderOpenCartDrawer(onCloseSpy);
136	
137	    await userEvent.click(screen.getByRole('button', { name: /close/i }));
138	
139	    expect(onCloseSpy).toHaveBeenCalledTimes(1);
140	  });
141	
142	  test('focus returns to finalFocusRef once the drawer finishes closing', async () => {
143	    const onCloseSpy = vi.fn();
144	    const trigger = await renderOpenCartDrawer(onCloseSpy);
145	
146	    await userEvent.click(screen.getByRole('button', { name: /close/i }));
147	
148	    // Real framer-motion exit transition (DRAWER_TRANSITION, ~300ms — zimmDrawer/index.tsx) has
149	    // to finish, and FocusLock has to release, before onCloseComplete/handleCloseComplete fires
150	    // — give waitFor real wall-clock room for it rather than relying on its default (1000ms)
151	    // budget.
152	    await waitFor(() => expect(trigger).toHaveFocus(), { timeout: 3000 });
153	  });
154	
155	  test('scroll position is genuinely restored on close, not merely that scroll-lock is released', async () => {
156	    // zimmDrawer/index.tsx's lock (module-level scrollLockCount/scrollLockPrev) only ever saves
157	    // and restores document.body.style.overflow — it has no window.scrollTo/scrollY logic of its
158	    // own. A test that only checks overflow returns to '' would pass even if some future change
159	    // to that mechanism reset the page's scroll position as a side effect. Pin a real, nonzero
160	    // scroll position independently and confirm it survives the whole open/close cycle
161	    // unchanged, instead of assuming "unlocked" implies "restored".
162	    Object.defineProperty(window, 'scrollY', { value: 850, writable: true, configurable: true });
163	
164	    const onCloseSpy = vi.fn();
165	    await renderOpenCartDrawer(onCloseSpy);
166	
167	    expect(document.body.style.overflow).toBe('hidden');
168	    expect(window.scrollY).toBe(850);
169	
170	    await userEvent.click(screen.getByRole('button', { name: /close/i }));
171	
172	    await waitFor(() => expect(document.body.style.overflow).not.toBe('hidden'));
173	    expect(window.scrollY).toBe(850);
174	  });
175	});
