// close button renders through ZimmButton -> ZimmIcon, so any test rendering the real ZimmDrawer
// (this whole file does, deliberately — see the comment below) needs this same mock. See
// testing.md's "Known gap: ZimmIcon throws under Vitest" and zimmButton/index.test.tsx for the
// identical precedent.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));

// This suite renders the REAL ZimmDrawer/Chakra Drawer/framer-motion throughout (nothing about
// the close mechanics is mocked), so Escape, backdrop-click, close-button, focus-restore and
// scroll-lock-restore all exercise ZimmDrawer's actual logic rather than a stand-in.
//
// A framer-motion AnimatePresence stub was tried here and reverted: Chakra's own
// ModalFocusScope (@chakra-ui/modal/dist/index.js) calls framer-motion's `usePresence()`
// itself, alongside — separately from — the `onExitComplete` prop ZimmDrawer's
// `onCloseComplete` depends on. A stub that only re-implements the `onExitComplete` callback
// (and doesn't also provide the real `usePresence` context, a materially bigger surface to
// reimplement faithfully) desynchronised FocusLock's own restore-focus timing from the real
// app's. Real framer-motion's ~300ms exit transition does complete correctly under this
// project's jsdom + Vitest setup; `waitFor`'s polling absorbs the wall-clock cost.

/** Mirrors real usage: the drawer starts CLOSED and only opens in response to a real click on
 *  its own trigger — never pre-opened on mount. This matters specifically for the focus-restore
 *  assertion below: Chakra's FocusLock (inside ZimmDrawer) captures "whichever element was
 *  active" at the moment IT activates as its own default restore-focus target, and
 *  userEvent.click() genuinely focuses the element it clicks (matching real Chrome/Firefox
 *  click behaviour) — so opening via a real click leaves the trigger focused *before* the
 *  drawer (and FocusLock) mounts, the same as real usage, rather than the drawer simply
 *  starting pre-opened with nothing having been focused at all. onCloseSpy observes that
 *  ZimmCartDrawer's onClose contract fires; the harness still has to actually flip isOpen
 *  itself (ZimmCartDrawer does not manage its own open state) so the real close path — and
 *  therefore the scroll-lock cleanup and onCloseComplete — actually run. */
function CartDrawerHarness({ onCloseSpy }: { onCloseSpy: () => void }) {
  const [isOpen, setIsOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  return (
    <ChakraProvider theme={theme}>
      <button ref={triggerRef} onClick={() => setIsOpen(true)}>
        Open bag
      </button>
      <ZimmCartDrawer
        isOpen={isOpen}
        onClose={() => {
          onCloseSpy();
          setIsOpen(false);
        }}
        itemCount={3}
        finalFocusRef={triggerRef}
      >
        <p>Line items</p>
      </ZimmCartDrawer>
    </ChakraProvider>
  );
}

/** Renders the harness and opens it via a real click on its own trigger — see
 *  CartDrawerHarness's own doc comment for why this matters. Returns the trigger element too,
 *  since the focus-restore test needs to assert on it by reference after the dialog unmounts. */
async function renderOpenCartDrawer(onCloseSpy: () => void) {
  render(<CartDrawerHarness onCloseSpy={onCloseSpy} />);
  const trigger = screen.getByRole('button', { name: 'Open bag' });
  await userEvent.click(trigger);
  await screen.findByRole('dialog');
  return trigger;
}

describe('ZimmCartDrawer', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('header title', () => {
    const renderWithItemCount = (itemCount: number) =>
      render(
        <ChakraProvider theme={theme}>
          <ZimmCartDrawer isOpen={true} onClose={vi.fn()} itemCount={itemCount}>
            <p>Line items</p>
          </ZimmCartDrawer>
        </ChakraProvider>,
      );

    test('renders "BAG • {itemCount}" while there are items', async () => {
      renderWithItemCount(3);
      expect(await screen.findByRole('dialog', { name: 'BAG • 3' })).toBeInTheDocument();
    });

    test('renders "BAG • {itemCount}" for a single item too (no singular/plural branching)', async () => {
      renderWithItemCount(1);
      expect(await screen.findByRole('dialog', { name: 'BAG • 1' })).toBeInTheDocument();
    });

    test('renders "YOUR BAG IS EMPTY" when itemCount is 0', async () => {
      renderWithItemCount(0);
      expect(await screen.findByRole('dialog', { name: 'YOUR BAG IS EMPTY' })).toBeInTheDocument();
    });
  });

  test('pressing Escape calls onClose', async () => {
    const onCloseSpy = vi.fn();
    await renderOpenCartDrawer(onCloseSpy);

    await userEvent.keyboard('{Escape}');

    expect(onCloseSpy).toHaveBeenCalledTimes(1);
  });

  test('clicking the backdrop calls onClose', async () => {
    const onCloseSpy = vi.fn();
    await renderOpenCartDrawer(onCloseSpy);
    const dialog = screen.getByRole('dialog');

    // ZimmDrawer's overlay-click-to-close handler (Chakra's getDialogContainerProps) lives on
    // ZimmDrawerContent's own outer container div, the dialog's direct DOM parent — not on
    // <DrawerOverlay> itself, which is purely visual (confirmed in @chakra-ui/modal/dist/
    // index.js: ModalOverlay carries no onClick at all). zimmDrawer/index.tsx's
    // ZimmDrawerContent renders `<chakra.div {...containerProps}><MotionChakraDiv
    // role="dialog" .../></chakra.div>` with no element in between, so the dialog's parent IS
    // that container. Clicking it exercises the same code path a real backdrop click does.
    const backdrop = dialog.parentElement as HTMLElement;
    await userEvent.click(backdrop);

    expect(onCloseSpy).toHaveBeenCalledTimes(1);
  });

  test('clicking the close button calls onClose', async () => {
    const onCloseSpy = vi.fn();
    await renderOpenCartDrawer(onCloseSpy);

    await userEvent.click(screen.getByRole('button', { name: /close/i }));

    expect(onCloseSpy).toHaveBeenCalledTimes(1);
  });

  test('focus returns to finalFocusRef once the drawer finishes closing', async () => {
    const onCloseSpy = vi.fn();
    const trigger = await renderOpenCartDrawer(onCloseSpy);

    await userEvent.click(screen.getByRole('button', { name: /close/i }));

    // Real framer-motion exit transition (DRAWER_TRANSITION, ~300ms — zimmDrawer/index.tsx) has
    // to finish, and FocusLock has to release, before onCloseComplete/handleCloseComplete fires
    // — give waitFor real wall-clock room for it rather than relying on its default (1000ms)
    // budget.
    await waitFor(() => expect(trigger).toHaveFocus(), { timeout: 3000 });
  });

  test('scroll position is genuinely restored on close, not merely that scroll-lock is released', async () => {
    // zimmDrawer/index.tsx's lock (module-level scrollLockCount/scrollLockPrev) only ever saves
    // and restores document.body.style.overflow — it has no window.scrollTo/scrollY logic of its
    // own. A test that only checks overflow returns to '' would pass even if some future change
    // to that mechanism reset the page's scroll position as a side effect. Pin a real, nonzero
    // scroll position independently and confirm it survives the whole open/close cycle
    // unchanged, instead of assuming "unlocked" implies "restored".
    Object.defineProperty(window, 'scrollY', { value: 850, writable: true, configurable: true });

    const onCloseSpy = vi.fn();
    await renderOpenCartDrawer(onCloseSpy);

    expect(document.body.style.overflow).toBe('hidden');
    expect(window.scrollY).toBe(850);

    await userEvent.click(screen.getByRole('button', { name: /close/i }));

    await waitFor(() => expect(document.body.style.overflow).not.toBe('hidden'));
    expect(window.scrollY).toBe(850);
  });
});

